#!/bin/sh
# Generated by esquadro: runs OpenTofu with the platform's secrets, which
# never touch the disk.
set -eu
secrets=../secrets/platform.sops.yaml
CLOUDFLARE_API_TOKEN=$(sops decrypt --extract '["cloudflare_token"]' "$secrets")
TF_VAR_state_passphrase=$(sops decrypt --extract '["tofu_passphrase"]' "$secrets")
export CLOUDFLARE_API_TOKEN TF_VAR_state_passphrase
exec tofu "$@"
